using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes =
        [
            new Recipe
            {
                Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
                Ingredients = "Pizza dough\nSan Marzano tomatoes\nFresh mozzarella\nFresh basil\nOlive oil\nSalt",
                Steps = "1. Preheat oven to 475°F (245°C).\n2. Roll out dough on a floured surface.\n3. Spread crushed tomatoes evenly.\n4. Tear mozzarella and distribute over sauce.\n5. Bake for 10–12 minutes until crust is golden.\n6. Top with fresh basil and a drizzle of olive oil.",
                Ratings = [5, 4, 5, 4, 5]
            },
            new Recipe
            {
                Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
                Ingredients = "Spaghetti\nGuanciale or pancetta\nEgg yolks\nPecorino Romano\nBlack pepper",
                Steps = "1. Cook spaghetti in salted water until al dente.\n2. Crisp guanciale in a skillet over medium heat.\n3. Whisk egg yolks with grated pecorino and pepper.\n4. Toss hot pasta with guanciale and remove from heat.\n5. Stir in egg mixture quickly, tossing to coat without scrambling.\n6. Serve immediately with extra pecorino.",
                Ratings = [5, 5, 4]
            },
            new Recipe
            {
                Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
                Ingredients = "Chicken breast\nYogurt\nGaram masala\nTurmeric\nCumin\nTomato sauce\nHeavy cream\nGarlic\nGinger\nOnion",
                Steps = "1. Marinate chicken in yogurt, garam masala, turmeric, and cumin for 1 hour.\n2. Grill or broil chicken until charred.\n3. Sauté onion, garlic, and ginger in a pan.\n4. Add tomato sauce and simmer 10 minutes.\n5. Stir in cream and add chicken pieces.\n6. Simmer for 15 minutes. Serve with rice or naan.",
                Ratings = [5, 4, 5, 5]
            },
            new Recipe
            {
                Id = 4, Title = "Vegetable Pad Thai", Category = "Asian",
                Ingredients = "Rice noodles\nTofu\nBean sprouts\nGreen onions\nPeanuts\nLime\nTamarind paste\nFish sauce\nSugar\nGarlic",
                Steps = "1. Soak rice noodles in warm water for 20 minutes.\n2. Press and cube tofu, then pan-fry until golden.\n3. Mix tamarind paste, fish sauce, and sugar for the sauce.\n4. Stir-fry garlic, then add noodles and sauce.\n5. Toss in tofu and bean sprouts.\n6. Serve topped with peanuts, green onions, and lime.",
                Ratings = [4, 4, 5]
            },
            new Recipe
            {
                Id = 5, Title = "Beef Tacos", Category = "Mexican",
                Ingredients = "Ground beef\nTaco shells\nLettuce\nTomato\nCheddar cheese\nSour cream\nChili powder\nCumin\nGarlic powder\nOnion",
                Steps = "1. Brown ground beef with diced onion in a skillet.\n2. Add chili powder, cumin, and garlic powder.\n3. Warm taco shells in the oven.\n4. Fill shells with seasoned beef.\n5. Top with shredded lettuce, diced tomato, cheese, and sour cream.",
                Ratings = [4, 3, 4, 5]
            },
            new Recipe
            {
                Id = 6, Title = "Chocolate Lava Cake", Category = "Desserts",
                Ingredients = "Dark chocolate\nButter\nEggs\nSugar\nFlour\nVanilla extract",
                Steps = "1. Preheat oven to 425°F (220°C). Grease ramekins.\n2. Melt chocolate and butter together.\n3. Whisk eggs and sugar until thick.\n4. Fold chocolate mixture into eggs, then fold in flour.\n5. Pour into ramekins and bake 12–14 minutes.\n6. Invert onto plates and serve immediately.",
                Ratings = [5, 5, 5, 4, 5]
            }
        ];
        _nextId = 7;
    }

    public List<RecipeCategory> GetCategories()
    {
        return
        [
            new RecipeCategory { Name = "Italian", Description = "Pasta, pizza, and Mediterranean classics", Icon = "🍝" },
            new RecipeCategory { Name = "Indian", Description = "Curries, spices, and vibrant flavors", Icon = "🍛" },
            new RecipeCategory { Name = "Asian", Description = "Stir-fries, noodles, and umami-rich dishes", Icon = "🥢" },
            new RecipeCategory { Name = "Mexican", Description = "Tacos, salsas, and bold seasonings", Icon = "🌮" },
            new RecipeCategory { Name = "Desserts", Description = "Sweet treats and baked goods", Icon = "🍰" }
        ];
    }

    public List<Recipe> GetRecipesByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetRecipeById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.Ratings.Add(stars);
        }
    }

    public Recipe AddRecipe(string title, string category, string ingredients, string steps)
    {
        var recipe = new Recipe
        {
            Id = _nextId++,
            Title = title,
            Category = category,
            Ingredients = ingredients,
            Steps = steps
        };
        _recipes.Add(recipe);
        return recipe;
    }
}

