arguments.file_text:
@page "/"

<PageTitle>RecipeShare — Home</PageTitle>

<h1>🍳 RecipeShare</h1>
<p class="lead">Discover and share delicious recipes from around the world.</p>

<div class="row mt-4">
    @foreach (var category in RecipeService.GetCategories())
    {
        <div class="col-md-4 mb-4">
            <div class="card h-100 shadow-sm">
                <div class="card-body text-center">
                    <h2 class="display-4">@category.Icon</h2>
                    <h5 class="card-title">@category.Name</h5>
                    <p class="card-text text-muted">@category.Description</p>
                    <a href="category/@category.Name" class="btn btn-outline-primary">Browse Recipes</a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Inject] public RecipeService RecipeService { get; set; } = default!;
}

@page "/category/{CategoryName}"

<PageTitle>@CategoryName Recipes — RecipeShare</PageTitle>

<h1>@GetCategoryIcon() @CategoryName Recipes</h1>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">@CategoryName</li>
    </ol>
</nav>

@if (Recipes.Count == 0)
{
    <div class="alert alert-info">No recipes found in this category yet.</div>
}
else
{
    <div class="row">
        @foreach (var recipe in Recipes)
        {
            <div class="col-md-6 mb-4">
                <div class="card h-100 shadow-sm">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text">
                            @if (recipe.Ratings.Count > 0)
                            {
                                <span class="text-warning">
                                    @for (int i = 1; i <= 5; i++)
                                    {
                                        @(i <= (int)Math.Round(recipe.AverageRating) ? "★" : "☆")
                                    }
                                </span>
                                <small class="text-muted">(@recipe.Ratings.Count ratings)</small>
                            }
                            else
                            {
                                <small class="text-muted">No ratings yet</small>
                            }
                        </p>
                        <a href="recipe/@recipe.Id" class="btn btn-primary btn-sm">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;
    [Inject] public RecipeService RecipeService { get; set; } = default!;

    private List<Recipe> Recipes { get; set; } = [];

    protected override void OnParametersSet()
    {
        Recipes = RecipeService.GetRecipesByCategory(CategoryName);
    }

    private string GetCategoryIcon()
    {
        var cat = RecipeService.GetCategories().FirstOrDefault(c => c.Name.Equals(CategoryName, StringComparison.OrdinalIgnoreCase));
        return cat?.Icon ?? "📖";
    }
}

@page "/recipe/{RecipeId:int}"

@if (Recipe is null)
{
    <PageTitle>Recipe Not Found — RecipeShare</PageTitle>
    <div class="alert alert-warning">Recipe not found.</div>
}
else
{
    <PageTitle>@Recipe.Title — RecipeShare</PageTitle>

    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="category/@Recipe.Category">@Recipe.Category</a></li>
            <li class="breadcrumb-item active">@Recipe.Title</li>
        </ol>
    </nav>

    <h1>@Recipe.Title</h1>
    <span class="badge bg-secondary mb-3">@Recipe.Category</span>

    <div class="row mt-3">
        <div class="col-md-4">
            <div class="card mb-3">
                <div class="card-header"><strong>Ingredients</strong></div>
                <ul class="list-group list-group-flush">
                    @foreach (var ingredient in Recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                    {
                        <li class="list-group-item">@ingredient</li>
                    }
                </ul>
            </div>
        </div>
        <div class="col-md-8">
            <h4>Instructions</h4>
            @foreach (var step in Recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
            {
                <p>@step</p>
            }
        </div>
    </div>

    <hr />

    <StarRating RecipeId="Recipe.Id" />
}

@code {
    [Parameter] public int RecipeId { get; set; }
    [Inject] public RecipeService RecipeService { get; set; } = default!;

    private Recipe? Recipe { get; set; }

    protected override void OnParametersSet()
    {
        Recipe = RecipeService.GetRecipeById(RecipeId);
    }
}

@rendermode InteractiveServer

<div class="card mt-3">
    <div class="card-body">
        <h5 class="card-title">Rate this Recipe</h5>

        @if (Submitted)
        {
            <div class="alert alert-success py-2 mb-2">Thanks for rating!</div>
        }

        <div class="d-flex align-items-center gap-1" style="font-size: 2rem; cursor: pointer;">
            @for (int i = 1; i <= 5; i++)
            {
                var star = i;
                <span @onclick="() => SubmitRating(star)"
                      @onmouseover="() => HoverRating = star"
                      @onmouseout="() => HoverRating = 0"
                      class="@(star <= DisplayRating ? "text-warning" : "text-muted")"
                      role="button"
                      aria-label="@star stars">★</span>
            }
        </div>

        @if (CurrentRecipe is not null && CurrentRecipe.Ratings.Count > 0)
        {
            <small class="text-muted mt-1 d-block">
                Average: @CurrentRecipe.AverageRating.ToString("F1") / 5
                (@CurrentRecipe.Ratings.Count ratings)
            </small>
        }
    </div>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Inject] public RecipeService RecipeService { get; set; } = default!;

    private int SelectedRating { get; set; }
