toolArgs.file_text:
@page "/recipe/{RecipeId:int}"

@if (Recipe is null)
{
    <PageTitle>Recipe Not Found — RecipeShare</PageTitle>
    <div class="alert alert-warning">Recipe not found.</div>
}
else
{
    <PageTitle>@Recipe.Title — RecipeShare</PageTitle>

    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="category/@Recipe.Category">@Recipe.Category</a></li>
            <li class="breadcrumb-item active">@Recipe.Title</li>
        </ol>
    </nav>

    <h1>@Recipe.Title</h1>
    <span class="badge bg-secondary mb-3">@Recipe.Category</span>

    <div class="row mt-3">
        <div class="col-md-4">
            <div class="card mb-3">
                <div class="card-header"><strong>Ingredients</strong></div>
                <ul class="list-group list-group-flush">
                    @foreach (var ingredient in Recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                    {
                        <li class="list-group-item">@ingredient</li>
                    }
                </ul>
            </div>
        </div>
        <div class="col-md-8">
            <h4>Instructions</h4>
            @foreach (var step in Recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
            {
                <p>@step</p>
            }
        </div>
    </div>

    <hr />

    <StarRating RecipeId="Recipe.Id" />
}

@code {
    [Parameter] public int RecipeId { get; set; }
    [Inject] public RecipeService RecipeService { get; set; } = default!;

    private Recipe? Recipe { get; set; }

    protected override void OnParametersSet()
    {
        Recipe = RecipeService.GetRecipeById(RecipeId);
    }
}

@rendermode InteractiveServer

<div class="card mt-3">
    <div class="card-body">
        <h5 class="card-title">Rate this Recipe</h5>

        @if (Submitted)
        {
            <div class="alert alert-success py-2 mb-2">Thanks for rating!</div>
        }

        <div class="d-flex align-items-center gap-1" style="font-size: 2rem; cursor: pointer;">
            @for (int i = 1; i <= 5; i++)
            {
                var star = i;
                <span @onclick="() => SubmitRating(star)"
                      @onmouseover="() => HoverRating = star"
                      @onmouseout="() => HoverRating = 0"
                      class="@(star <= DisplayRating ? "text-warning" : "text-muted")"
                      role="button"
                      aria-label="@star stars">★</span>
            }
        </div>

        @if (CurrentRecipe is not null && CurrentRecipe.Ratings.Count > 0)
        {
            <small class="text-muted mt-1 d-block">
                Average: @CurrentRecipe.AverageRating.ToString("F1") / 5
                (@CurrentRecipe.Ratings.Count ratings)
            </small>
        }
    </div>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Inject] public RecipeService RecipeService { get; set; } = default!;

    private int SelectedRating { get; set; }
    private int HoverRating { get; set; }
    private bool Submitted { get; set; }
    private Recipe? CurrentRecipe { get; set; }

    private int DisplayRating => HoverRating > 0 ? HoverRating : SelectedRating;

    protected override void OnParametersSet()
    {
        CurrentRecipe = RecipeService.GetRecipeById(RecipeId);
    }

    private void SubmitRating(int stars)
    {
        SelectedRating = stars;
        RecipeService.AddRating(RecipeId, stars);
        CurrentRecipe = RecipeService.GetRecipeById(RecipeId);
        Submitted = true;
    }
}

